DELETE FROM kit_job_log_glue
WHERE id NOT IN (
    SELECT id FROM (
        SELECT id FROM kit_job_log_glue
        WHERE job_id = #{jobId}
        ORDER BY modify_time DESC
        LIMIT 0, #{limit}
    ) t1
) AND job_id = #{jobId}

DELETE FROM kit_job_log_glue
WHERE id NOT IN (
    SELECT id FROM (
        SELECT id FROM kit_job_log_glue
        WHERE job_id = #{jobId}
        ORDER BY modify_time DESC
        LIMIT #{limit} OFFSET 0
    ) t1
) AND job_id = #{jobId}
